inline NfsCompactCaptionWordView word(const nfs_compact_caption_display::Artwork&a){NfsCompactCaptionWordView v{};v.schema=1;v.word=3;v.width=192;v.height=128;v.rgba=a.rgba.data();v.bytes=a.rgba.size();std::copy(a.sha.begin(),a.sha.end(),v.sha256);v.left=120;v.top=364;v.right=168;v.bottom=396;return v;}
inline double alpha(const nfs_compact_caption_display::Artwork&a,double x,double y){if(x<120||x>=168||y<364||y>=396)return 0;double X=std::max(0.,std::min(191.,(x-120)*4-.5)),Y=std::max(0.,std::min(127.,(y-364)*4-.5));unsigned i=unsigned(X),j=unsigned(Y),k=std::min(i+1,191u),l=std::min(j+1,127u);double fx=X-i,fy=Y-j;auto at=[&](unsigned x,unsigned y){return double(a.rgba[(size_t(y)*192+x)*4+3]);};return (at(i,j)*(1-fx)+at(k,j)*fx)*(1-fy)+(at(i,l)*(1-fx)+at(k,l)*fx)*fy;}
template<class T>void image(T&t,const std::vector<unsigned char>&pixels,const nfs_compact_caption_display::Artwork&a){const double ratio=t.h/480.;unsigned opaque=0,edge=0,clear=0;const int panel[3]={90,60,30};for(unsigned y=unsigned(362*ratio);y<unsigned(398*ratio);++y)for(unsigned x=unsigned(118*ratio);x<unsigned(170*ratio);++x){double A=alpha(a,(x+.5)/ratio,(y+.5)/ratio);opaque+=A>254;edge+=A>2&&A<253;clear+=A<1;size_t at=(size_t(t.h-1-y)*t.w+x)*4;for(unsigned k=0;k<3;++k)ck(std::abs(int(pixels[at+k])-int(std::lround(A+panel[k]*(1-A/255.))))<=2,"nested pinned word3 exact RGBA, bounds and transparent padding");}ck(opaque>40&&edge>30&&clear>100,"nested word3 retains opaque glyph and smooth antialiasing");}
struct PrepareOwner{EGLContext context;uint64_t generation;std::thread::id thread=std::this_thread::get_id();static int current(void*p,const NfsBackgroundSceneStage*t){auto&o=*static_cast<PrepareOwner*>(p);return t&&eglGetCurrentContext()==o.context&&std::this_thread::get_id()==o.thread&&t->generation==o.generation&&t->contextIdentity==uintptr_t(o.context);}};
template<class G,class L,class D,class T>void layers(G gpu,L original,D draw,T&t,const NfsBackgroundSceneStage&stage,const std::vector<unsigned char>&baseline,std::vector<GLuint>aliases){
 auto a=nfs_compact_caption_display::artwork(3);ck(bool(a)&&a->width==192&&a->height==128,"actual pinned nested Options artwork");auto v=original;v.sidebarWord=word(*a);NfsNestedCaptionGpu resource{};gpu.sidebarWord=&resource;PrepareOwner owner{eglGetCurrentContext(),stage.generation};auto guard=stage;guard.framebuffer=0;guard.ownerCurrent=PrepareOwner::current;guard.ownerUser=&owner;const auto before=capture();ck(nfs_nested_caption_prepare(&resource,&v.sidebarWord,3,&guard)&&equal(before,capture()),"nested word cold resource preparation restores state");const auto saved=resource;ck(nfs_nested_caption_prepare(&resource,&v.sidebarWord,3,&guard)&&resource.program==saved.program&&resource.texture==saved.texture&&equal(before,capture()),"nested warm preparation retains exact GPU resources");
 t.seed();t.bind();glViewport(stage.sampling.viewport[0],stage.sampling.viewport[1],stage.sampling.viewport[2],stage.sampling.viewport[3]);auto state=capture();drawCount=0;programs.clear();ck(draw(&gpu,&stage,&v)&&equal(state,capture()),"nested adopted word draws with complete state restoration");auto rendered=t.read();image(t,rendered,*a);ck(std::find(programs.begin(),programs.end(),resource.program)!=programs.end()&&std::find(programs.begin(),programs.end(),gpu.sidebarCaption->program)==programs.end()&&std::find(programs.begin(),programs.end(),gpu.text->program)!=programs.end(),"only software sidebar draw replaced; full dialog text remains");
 // Compare every unchanged pixel, including Audio bars, the full text and all
 // background art. Only original source-caption and new-word boxes may differ.
 float l=640,top=480,r=0,b=0;for(size_t i=0;i<v.sidebarCaption.vertexCount;++i){auto&q=v.sidebarCaption.vertices[i];l=std::min(l,q.x);top=std::min(top,q.y);r=std::max(r,q.x);b=std::max(b,q.y);}const double ratio=t.h/480.;for(unsigned y=0;y<t.h;++y)for(unsigned x=0;x<t.w;++x){double X=(x+.5)/ratio,Y=(y+.5)/ratio;if((X>=l-1&&X<=r+1&&Y>=top-1&&Y<=b+1)||(X>=119&&X<=169&&Y>=363&&Y<=397))continue;size_t at=(size_t(t.h-1-y)*t.w+x)*4;ck(!std::memcmp(rendered.data()+at,baseline.data()+at,4),"nested replacement preserves every unrelated layer pixel");}
 t.seed();t.bind();glViewport(0,0,stage.sampling.viewport[2],stage.sampling.viewport[3]);const auto clean=t.read();state=capture();for(unsigned f=0;f<14;++f){auto bad=v;auto bytes=a->rgba;if(f==0)bad.sidebarWord.schema=0;if(f==1)bad.sidebarWord.word=2;if(f==2)--bad.sidebarWord.width;if(f==3)--bad.sidebarWord.height;if(f==4)--bad.sidebarWord.bytes;if(f==5)bad.sidebarWord.rgba=nullptr;if(f==6)bad.sidebarWord.sha256[0]^=1;if(f==7){bytes[3]^=1;bad.sidebarWord.rgba=bytes.data();}if(f==8)bad.sidebarWord.left++;if(f==9)bad.sidebarWord.top++;if(f==10)bad.sidebarWord.right++;if(f==11)bad.sidebarWord.bottom++;if(f==12)bad.sidebarWord.left=NAN;if(f==13)bad.sidebarWord.top=INFINITY;drawCount=0;ck(!draw(&gpu,&stage,&bad)&&!drawCount&&equal(state,capture())&&t.read()==clean,"nested malformed/cross-word/bounds pin rejects before any draw");}
 aliases.push_back(t.texture);aliases.push_back(gpu.sidebarCaption->texture);aliases.push_back(gpu.text->texture);aliases.push_back(gpu.background->textures[0]);aliases.push_back(gpu.background->logo.texture);for(auto alias:aliases){if(!alias)continue;resource.texture=alias;drawCount=0;ck(!draw(&gpu,&stage,&v)&&!drawCount&&equal(state,capture())&&t.read()==clean&&glIsTexture(alias),"nested borrowed resource alias rejects without deleting or drawing");resource=saved;}
 {auto broken=gpu;broken.sidebarWord=nullptr;drawCount=0;ck(!draw(&broken,&stage,&v)&&!drawCount&&t.read()==clean,"nonempty nested word requires its independently prepared resource");}
 ck(nfs_nested_caption_retire(&resource,&guard,1)&&!resource.program&&!resource.texture&&!glIsProgram(saved.program)&&!glIsTexture(saved.texture),"nested owner retirement releases exact word resources");
}
